/// Provider quota & budget monitoring models (issue #823).
///
/// Pure Dart: no `dart:io`, no network. Adapters take an injectable
/// `http.Client`; the service caches; surfaces (CLI /quota, badge, app
/// meters) render from cache only and never block on a fetch.
///
/// Semantics:
/// - `unknown` (a `QuotaFetchResult` with a null quota and a one-line
///   reason) is DISTINCT from `unmetered` (a real `ProviderQuota` with
///   `isUnmetered: true`): unknown means "we could not ask", unmetered
///   means "there is no billing surface".
/// - A null `limit` means the provider tracks usage but caps nothing
///   (prepaid / unlimited); rendering shows `no cap` / `unlimited`, and
///   such providers are never depleted.
library;

import 'package:http/http.dart' as http;

/// Unit a provider's allowance is measured in.
enum QuotaUnit {
  currencyUsd('currencyUsd'),
  requests('requests'),
  tokens('tokens'),
  unmetered('unmetered');

  const QuotaUnit(this.value);

  /// The JSON name written by [toJson] — a pinned literal, so renaming
  /// the identifier cannot silently change persisted values.
  final String value;

  String toJson() => value;

  /// Tolerant parse: null/unknown falls back to [currencyUsd] (the
  /// historical default — quota reads must never crash on a future or
  /// corrupted unit spelling).
  static QuotaUnit fromJson(Object? value) => switch (value) {
    'requests' => requests,
    'tokens' => tokens,
    'unmetered' => unmetered,
    _ => currencyUsd,
  };
}

/// A provider's remaining-allowance snapshot at [updatedAt].
class ProviderQuota {
  final double? used;
  final double? limit;
  final QuotaUnit unit;
  final DateTime? resetsAt;
  final bool isUnmetered;
  final DateTime updatedAt;

  ProviderQuota({
    this.used,
    this.limit,
    this.unit = QuotaUnit.currencyUsd,
    this.resetsAt,
    this.isUnmetered = false,
    DateTime? updatedAt,
  }) : updatedAt = updatedAt ?? DateTime.now().toUtc();

  /// DIAL-style providers with no billing surface at all: reported
  /// silently, never an error.
  factory ProviderQuota.unmetered({DateTime? updatedAt}) => ProviderQuota(
    unit: QuotaUnit.unmetered,
    isUnmetered: true,
    updatedAt: updatedAt,
  );

  /// `limit - used`, or null when either side is unknown.
  double? get remaining =>
      (limit != null && used != null) ? limit! - used! : null;

  /// Metered and exhausted. A null limit (no cap) is never depleted.
  bool get isDepleted => limit != null && used != null && used! >= limit!;

  /// True past a declared reset point: the cached limit is stale after a
  /// billing reset and must not persist (E4).
  bool isResetOverdue(DateTime now) =>
      resetsAt != null && now.isAfter(resetsAt!);

  Map<String, Object?> toJson() => {
    'used': used,
    'limit': limit,
    'unit': unit.toJson(),
    if (resetsAt != null) 'resetsAt': resetsAt!.toUtc().toIso8601String(),
    if (isUnmetered) 'isUnmetered': true,
    'updatedAt': updatedAt.toUtc().toIso8601String(),
  };

  factory ProviderQuota.fromJson(Map<String, Object?> json) => ProviderQuota(
    used: (json['used'] as num?)?.toDouble(),
    limit: (json['limit'] as num?)?.toDouble(),
    unit: QuotaUnit.fromJson(json['unit']),
    resetsAt: json['resetsAt'] is String
        ? DateTime.parse(json['resetsAt'] as String)
        : null,
    isUnmetered: json['isUnmetered'] == true,
    updatedAt: json['updatedAt'] is String
        ? DateTime.parse(json['updatedAt'] as String)
        : DateTime.fromMillisecondsSinceEpoch(0, isUtc: true),
  );

  @override
  String toString() =>
      'ProviderQuota(${formatQuotaUsedLimit(this)}, '
      'reset: ${formatQuotaReset(resetsAt, updatedAt)})';
}

/// Result of one quota fetch: either a parsed [ProviderQuota] or an
/// `unknown` with a one-line reason (E2/E3 — no retry storms, no errors
/// surfaced to the user beyond the reason).
class QuotaFetchResult {
  final ProviderQuota? quota;
  final String? reason;

  const QuotaFetchResult.ok(ProviderQuota this.quota) : reason = null;
  const QuotaFetchResult.unknown(String this.reason) : quota = null;

  bool get isUnknown => quota == null;

  @override
  String toString() => isUnknown
      ? 'QuotaFetchResult(unknown: $reason)'
      : 'QuotaFetchResult($quota)';
}

/// Per-provider quota source: pure parse + injectable [http.Client].
/// Adapters never cache (the service does) and never throw — every
/// failure degrades to `QuotaFetchResult.unknown`.
abstract interface class QuotaAdapter {
  Future<QuotaFetchResult> fetch();
}

/// Capability interface for quota-aware surfaces: providers (or their
/// adapter facades) opt in; absence of the capability renders as
/// `unknown` — never an error.
abstract interface class QuotaAwareProvider {
  Future<ProviderQuota?> fetchQuota({bool forceRefresh});
}

/// Resolver-facing view of quota depletion. A depleted provider is a
/// deprioritization hint only — the resolver stays the single decision
/// point and never hard-blocks on quota.
abstract interface class QuotaFeed {
  bool isDepleted(String providerId);
}

/// Formats one amount: `$48.20` / `$150` / `1840`. Currency keeps two
/// decimals unless the value is integral.
String formatQuotaAmount(double? value, QuotaUnit unit) {
  if (value == null) return '…';
  final String body;
  if (unit == QuotaUnit.currencyUsd) {
    body = _trimNumber(value, value % 1 == 0 ? 0 : 2);
    return '\$$body';
  }
  return _trimNumber(value, 0);
}

String _trimNumber(double value, int fractionDigits) =>
    value.toStringAsFixed(fractionDigits);

/// Renders the used/limit column: `unknown` for a null quota (capability
/// absent or fetch failed — never a `null` literal, E2), `unmetered` for
/// billing-free providers, `$48.20/$150` when both sides are known,
/// `$48.20/no cap` for uncapped prepaid, `unlimited` when nothing is
/// reported at all, `…/$150` when only the limit is known.
String formatQuotaUsedLimit(ProviderQuota? quota) {
  if (quota == null) return 'unknown';
  if (quota.isUnmetered || quota.unit == QuotaUnit.unmetered) {
    return 'unmetered';
  }
  final used = formatQuotaAmount(quota.used, quota.unit);
  final limit = quota.limit == null
      ? null
      : formatQuotaAmount(quota.limit, quota.unit);
  if (quota.used == null && limit == null) return 'unlimited';
  if (limit == null) return '$used/no cap';
  return '$used/$limit';
}

/// Reset countdown: `''` when unknown, `reset overdue` in the past (E4),
/// otherwise the coarsest nonzero unit (`11d` / `5h` / `3m` / `<1m`).
String formatQuotaReset(DateTime? resetsAt, DateTime now) {
  if (resetsAt == null) return '';
  if (!now.isBefore(resetsAt)) return 'reset overdue';
  final delta = resetsAt.difference(now);
  if (delta.inDays >= 1) return '${delta.inDays}d';
  if (delta.inHours >= 1) return '${delta.inHours}h';
  if (delta.inMinutes >= 1) return '${delta.inMinutes}m';
  return '<1m';
}

/// Status-badge string for the ACTIVE provider: `[OR $48/$150 · 11d]`.
/// Cold cache renders `[OR …]`; unmetered providers render nothing
/// (silent — they must not crowd the status line, AC7).
String formatQuotaBadge({
  required String shortName,
  ProviderQuota? quota,
  required DateTime now,
}) {
  if (quota == null) return '[$shortName …]';
  if (quota.isUnmetered || quota.unit == QuotaUnit.unmetered) return '';
  final isCurrency = quota.unit == QuotaUnit.currencyUsd;
  String? short(double? v) =>
      v == null ? null : '${isCurrency ? r'$' : ''}${_trimNumber(v, 0)}';
  final used = short(quota.used);
  final limit = short(quota.limit);
  final ratio = used == null && limit == null
      ? 'unlimited'
      : limit == null
      ? '${used ?? "…"}/no cap'
      : '$used/$limit';
  final reset = formatQuotaReset(quota.resetsAt, now);
  return '[$shortName $ratio${reset.isEmpty ? '' : ' · $reset'}]';
}

/// L9 (last): high-entropy token heuristic.
///
/// Secret-shaped ASCII token runs (`[A-Za-z0-9+=_-]`, at least
/// `minLength` chars) whose Shannon entropy reaches `minEntropy` are
/// masked - but only when no higher-priority layer already claimed the
/// span, and never for well-known STRUCTURED values:
///
/// - `/` is deliberately NOT a token character: it is a path separator,
///   so a filesystem path never glues into one giant "secret" (mixed-case
///   paths cross `minEntropy` easily and every ls/find/read listing would
///   shred). Base64 rarely needs `/`; when it has one, the surrounding
///   segments still match individually.
/// - a token immediately after `/` is a path component, not a value.
/// - UUIDs, pure-hex runs, ISO-timestamp-prefixed ids, and subresource
///   integrity hashes (`sha256-...`) are public structure, not secrets.
library;

import 'dart:math' as math;

import 'redaction_types.dart';

/// Marker label used for high-entropy spans.
const String highEntropyLabel = 'High Entropy String';

final RegExp _uuidShape = RegExp(
  r'^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}'
  r'-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$',
);
final RegExp _hexRun = RegExp(r'^[0-9a-fA-F][0-9a-fA-F_-]+$');
final RegExp _isoTimestamp = RegExp(r'^\d{4}-\d{2}-\d{2}T');
final RegExp _integrityHash = RegExp(r'^sha(256|384|512)-');

/// gh-1952 (I3): compile-time defines and env-style assignments are not
/// secrets by default. The token charset includes `=` and `-`, so a
/// whole define argument is ONE candidate token — the incident command's
/// `--dart-define=JSR_THREE_EXAMPLE=webgl_geometry_colors` crossed the
/// entropy threshold and the redactor rewrote it into a marker that then
/// reached the child process. These shapes are exempt from THIS
/// heuristic only; the real secret layers (registered, vendor, pem,
/// context, ...) outrank the entropy layer and still match inside
/// defines.
/// The bare-assignment exemption is value-gated (see
/// [_isDefineOrAssignmentToken]) so it cannot silence the net for
/// `KEY=<random>` secrets or padded base64.
final RegExp _dartDefineFlag = RegExp(r'^--dart-define=');
final RegExp _dartDefineShortFlag = RegExp(r'^-D[A-Za-z_][A-Za-z0-9_.]*=');
final RegExp _envAssignment = RegExp(r'^[A-Za-z_][A-Za-z0-9_.]{0,63}=');

/// Whether [token] reads as a define argument (`--dart-define=K=V`,
/// `-DK=V`) or an env-style `K=V` assignment. Quoted define values
/// (`--dart-define="K=V"`) tokenize without the flag prefix but still
/// carry the `K=V` assignment shape. Shape-based, not configurable
/// (gh-1952 non-goals).
///
/// gh-1952 review tightening: the flag forms are exempt unconditionally
/// (every incident repro shape carries one), but a bare `K=V` token is
/// exempt only when it cannot be a secret itself — the key is a bounded
/// identifier, the token does not end in base64 padding (`=`/`==`), and
/// the VALUE side reads as an ordinary low-entropy build input. A
/// `KEY=<random>` assignment (`printenv`/CI-log output) and a
/// padded-base64 token keep their entropy-layer net: this layer also
/// runs on the display/persistence pipeline, where those classes were
/// masked before the carve-out existed.
bool _isDefineOrAssignmentToken(String token, double minEntropy) {
  if (_dartDefineFlag.hasMatch(token)) return true;
  if (_dartDefineShortFlag.hasMatch(token)) return true;
  final assignment = _envAssignment.firstMatch(token);
  if (assignment == null) return false;
  if (token.endsWith('=')) return false; // base64 padding, not a key end
  final value = token.substring(assignment.end);
  return value.isNotEmpty && shannonEntropy(value) < minEntropy;
}

/// Whether [token] is a well-known safe structured value a secret never
/// takes the shape of (public hashes, ids, timestamps).
bool isStructuredIdentifier(String token) {
  if (_uuidShape.hasMatch(token)) return true;
  if (_hexRun.hasMatch(token)) return true;
  if (_isoTimestamp.hasMatch(token)) return true;
  if (_integrityHash.hasMatch(token)) return true;
  return false;
}

/// Shannon entropy of [token] in bits per character.
double shannonEntropy(String token) {
  final counts = <int, int>{};
  for (final c in token.codeUnits) {
    counts[c] = (counts[c] ?? 0) + 1;
  }
  var entropy = 0.0;
  final n = token.length;
  for (final count in counts.values) {
    final p = count / n;
    entropy -= p * (math.log(p) / math.ln2);
  }
  return entropy;
}

/// Finds high-entropy ASCII token spans in [text].
///
/// [prior] holds matches from higher-priority layers; tokens inside those
/// spans are skipped.
List<RedactionMatch> layerEntropy(
  String text,
  RedactionConfig cfg, {
  List<RedactionMatch> prior = const [],
}) {
  final minLength = cfg.minLength;
  if (text.length < minLength) return const [];
  final pattern = RegExp('[A-Za-z0-9+=_-]{$minLength,}');
  final matches = <RedactionMatch>[];
  for (final m in pattern.allMatches(text)) {
    final token = [REDACTED:Sensitive-Value])!;
    // Alphabet-length guard: a real secret never uses a tiny alphabet.
    if (token.codeUnits.toSet().length < 8) continue;
    // gh-1952 (I3): defines and env-style assignments are not secrets
    // by default — exempt before the entropy math (the review-tightened
    // gate keeps `KEY=<random>`-shaped secrets covered).
    if (_isDefineOrAssignmentToken(token, cfg.minEntropy)) continue;
    if (shannonEntropy(token) < cfg.minEntropy) continue;
    if (isStructuredIdentifier(token)) continue;
    // A token glued after `/` is a path component, not a standalone
    // value - real secrets do not live in directory names.
    if (m.start > 0 && text[m.start - 1] == '/') continue;
    final match = RedactionMatch(
      start: m.start,
      end: m.end,
      layer: RedactionLayer.entropy,
      kindLabel: highEntropyLabel,
    );
    if (prior.any(match.overlaps) || matches.any(match.overlaps)) continue;
    matches.add(match);
  }
  return matches;
}

